/* From Uiverse.io by alexruix - Tags: profile, gradient, card */
.__UIV_SCOPE__ .card {
  overflow: visible;
  position: relative;
  width: 190px;
  height: 254px;
  background: #fff;
  box-shadow: 0 2px 10px rgba(0, 0, 0, .2);
}

.__UIV_SCOPE__ .card:before,
.__UIV_SCOPE__ .card:after {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  border-radius: 4px;
  background: #fff;
  transition: 0.5s;
  z-index: -99;
}

.__UIV_SCOPE__ .details {
  position: absolute;
  left: -10px;
  right: 0;
  bottom: 5px;
  height: 60px;
  text-align: center;
  text-transform: uppercase;
}

/*Image*/
.__UIV_SCOPE__ .imgbox {
  position: absolute;
  top: 10px;
  left: 10px;
  bottom: 10px;
  right: 10px;
  background: #222;
  transition: 0.5s;
  z-index: 1;
}

.__UIV_SCOPE__ .img {
  background: #4158D0;
  background-image: linear-gradient(45deg, #4158D0, #C850C0);
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
}

/*Text*/
.__UIV_SCOPE__ .title {
  font-weight: 600;
  font-size: 20px;
  color: #777;
}

.__UIV_SCOPE__ .caption {
  font-weight: 500;
  font-size: 16px;
  color: #4158D0;
  display: block;
  margin-top: 5px;
}

/*Hover*/
.__UIV_SCOPE__ .card:hover .imgbox {
  bottom: 80px;
}

.__UIV_SCOPE__ .card:hover:before {
  transform: rotate(20deg);
}

.__UIV_SCOPE__ .card:hover:after {
  transform: rotate(10deg);
  box-shadow: 0 2px 20px rgba(0, 0, 0, .2);
}
